const taskMap = new Map(tasks.map(t => [t.id, t]));
const inDegree = new Map(tasks.map(t => [t.id, t.deps.length]));
const dependents = new Map(tasks.map(t => [t.id, []]));

// Build dependent lists
for (const t of tasks) {
  for (const d of t.deps) {
    dependents.get(d).push(t.id);
  }
}

const queue = [];
for (const t of tasks) {
  if (inDegree.get(t.id) === 0) queue.push(t);
}

const sorted = [];
while (queue.length > 0) {
  // Pop in deterministic order (by id) if multiple available
  queue.sort((a, b) => a.id.localeCompare(b.id));
  const t = queue.shift();
  sorted.push(t);
  for (const depId of dependents.get(t.id)) {
    const newIn = inDegree.get(depId) - 1;
    inDegree.set(depId, newIn);
    if (newIn === 0) queue.push(taskMap.get(depId));
  }
}

return { sortedTasks: sorted };
"}
